COURSE = dict(id="global-investing", level="practitioner", title="Investing overseas from India", sec="nri", track="global", topic="Global", tag="Global",
  blurb="How Indian residents can invest abroad, the limits and taxes that apply, and the risks of global markets.",
  hook="Global investing spreads risk beyond one country, but it adds rules, currency swings and tax steps most people do not expect.",
  fun=["Indian residents can send a fixed amount abroad each financial year under a scheme called LRS.", "Some Indian funds that invest overseas pause new investments when industry-wide limits are reached."],
  traps=["Using unregistered apps that promise easy global trading.", "Ignoring currency risk and tax reporting.", "Putting too much money in a single overseas theme."],
  lessons=[
  dict(title="The remittance rules", intro="Sending money abroad to invest is allowed within rules set by RBI.", concepts=[
    ("LRS", "LRS is the Liberalised Remittance Scheme, which allows a resident individual to send up to a set amount abroad each financial year for permitted purposes.", "A resident sends money to an overseas broker under a yearly RBI limit to buy foreign shares."),
    ("Permitted purpose", "A permitted purpose is a use of remitted money that the rules allow, such as investing, education, travel or gifts.", "A person declares investment as the purpose of the transfer."),
    ("TCS on remittance", "TCS on remittance is tax collected at source by the bank on certain overseas transfers, which can usually be adjusted against your tax liability.", "A bank collects tax when a large amount is sent abroad."),
    ("Authorised dealer bank", "An authorised dealer bank is a bank permitted by RBI to handle foreign exchange transactions.", "A resident sends funds through such a bank to an overseas broker.")],
    client=("“How much can I send abroad to invest?”", "A client wanting to buy US stocks."), talk="“There is a yearly limit per person under LRS, and the bank may collect tax at source. Use only an authorised bank and keep the records.”", remember=["LRS has a yearly cap.", "Purpose must be declared.", "TCS may apply."]),
  dict(title="Ways to invest abroad", intro="There are several routes, each with a different level of effort, cost and risk.", concepts=[
    ("Feeder fund", "A feeder fund is an Indian mutual fund that invests in a fund listed overseas, so you invest in rupees without sending money abroad yourself.", "An investor buys an Indian fund that tracks a US technology fund."),
    ("Fund of funds", "A fund of funds is a fund that invests in other funds rather than directly in shares.", "An Indian scheme holds units of several global equity funds."),
    ("Direct foreign account", "A direct foreign account is a brokerage account abroad that an Indian resident opens to buy overseas shares or ETFs under LRS.", "A resident buys an overseas ETF through such an account."),
    ("Overseas index", "An overseas index is a benchmark of foreign companies, such as a US large-company index, that a fund may track.", "A fund aims to mirror a global stock index.")],
    client=("“Should I buy US stocks directly or use a fund?”", "A client comparing routes."), talk="“A fund is simpler and stays in rupees. A direct account gives more choice but adds paperwork, tax reporting and currency handling.”", remember=["Funds are simpler.", "Direct needs LRS.", "Check limits and costs."]),
  dict(title="Global risks", intro="Foreign markets bring their own risks on top of normal market risk.", concepts=[
    ("Currency risk", "Currency risk is the chance that rupee and foreign currency moves change your return when converted back.", "A foreign fund gains in dollars but the rupee value rises less."),
    ("Concentration risk", "Concentration risk is the danger of having too much money in one country, sector or theme.", "A portfolio holds mostly a few global technology companies."),
    ("Tracking error", "Tracking error is the gap between what an index fund returns and what the index returns.", "A fund returns slightly less than its index due to costs."),
    ("Subscription limit", "A subscription limit is a cap on new money a fund investing overseas can accept, which may pause fresh investments.", "A fund stops accepting lump sums for a period.")],
    client=("“Why did my SIP in the global fund stop?”", "A client who got a notice."), talk="“Funds investing overseas have industry limits. When the limit is reached, new investments can pause. Your existing units are not lost.”", remember=["Currency can help or hurt.", "Avoid single-theme bets.", "Limits can pause SIPs."]),
  dict(title="Tax and reporting", intro="Overseas assets must be reported, and the tax depends on the product and holding period.", concepts=[
    ("Capital gains on overseas assets", "Capital gains on overseas assets are taxed in India according to the type of asset, the holding period and the rates in force.", "A resident sells foreign shares and pays tax on the gain in India."),
    ("Schedule FA", "Schedule FA is the part of the Indian tax return where residents disclose foreign assets and accounts.", "A resident lists an overseas brokerage account in the return."),
    ("Withholding on dividends", "Withholding on dividends is tax deducted by the foreign country before a dividend reaches you.", "A foreign dividend arrives after tax has been cut."),
    ("Foreign tax credit", "Foreign tax credit lets you offset tax paid abroad against Indian tax on the same income, as the rules allow.", "A resident claims credit for tax withheld on a dividend.")],
    client=("“Do I need to tell the tax office about my US account?”", "A client with a new overseas broker."), talk="“Yes. Residents must disclose foreign assets in the return. Missing this can bring penalties, so we will keep the statements ready.”", remember=["Disclose foreign assets.", "Tax depends on product and period.", "Claim credit for foreign tax."]),
  dict(title="Staying safe", intro="Global investing attracts scams. A few habits protect you.", concepts=[
    ("Regulated channel", "A regulated channel is a broker, bank or fund house authorised by the proper regulator to handle your money.", "An investor uses an authorised bank and a registered fund house."),
    ("Diversification", "Diversification is spreading money across assets, countries and sectors so one problem does not sink the portfolio.", "An investor keeps global funds as one part of a larger plan."),
    ("Unregistered app", "An unregistered app is a platform with no regulatory approval that promises easy global trading, and it is a common route for fraud.", "A social media ad promotes a trading app that asks for deposits to a personal account."),
    ("Time horizon", "Time horizon is how long you can leave money invested, which should match the risk of the investment.", "A person who needs money in a year avoids volatile global equity.")],
    client=("“A Telegram group offers guaranteed returns on US stocks.”", "A client tempted by a group."), talk="“No genuine investment can guarantee returns. Check that the entity is regulated before sending any money.”", remember=["Use regulated channels.", "Never trust guaranteed returns.", "Match risk to time horizon."]),
  ])
